-- CulinaryBlog content translation from validated PostgreSQL backup.
-- All replacement text is English and ASCII; no Unicode code-page loss.
-- Generated from 100 clean seed templates mapped to live UUIDs.
-- Preserves user accounts, passwords, auth tokens, IDs, slugs, relationships,
-- status, difficulty, numeric values, images, and creation timestamps.
-- Only five known seed chef names/bios are converted to plain English;
-- the six unrelated user profiles are not modified.
-- TEST THIS ON A RESTORED COPY BEFORE RUNNING ON YOUR REAL DATABASE.
-- The statements below are wrapped in one transaction with count guards.
-- Only human-facing content columns are modified.

BEGIN;

CREATE TEMP TABLE _en_recipes (id uuid PRIMARY KEY, title text NOT NULL, description text NOT NULL, instructions text NOT NULL, notes text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _en_categories (id uuid PRIMARY KEY, name text NOT NULL, description text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _en_ingredients (id uuid PRIMARY KEY, name text NOT NULL, unit text NOT NULL, notes text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _en_steps (id uuid PRIMARY KEY, title text NOT NULL, description text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _en_images (id uuid PRIMARY KEY, alt_text text NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE _en_users (id uuid PRIMARY KEY, full_name text NOT NULL, bio text NOT NULL) ON COMMIT DROP;

-- Fail safely if target database has diverged from this backup.
DO $validate$
BEGIN
    IF (SELECT COUNT(*) FROM _en_categories) <> 27 THEN
        RAISE EXCEPTION 'Invalid category seed count';
    END IF;

    IF (SELECT COUNT(*) FROM _en_recipes) <> 100 THEN
        RAISE EXCEPTION 'Invalid recipe seed count';
    END IF;

    IF (SELECT COUNT(*) FROM _en_ingredients) <> 1161 THEN
        RAISE EXCEPTION 'Invalid ingredient seed count';
    END IF;

    IF (SELECT COUNT(*) FROM _en_steps) <> 605 THEN
        RAISE EXCEPTION 'Invalid step seed count';
    END IF;

    IF (SELECT COUNT(*) FROM _en_images) <> 100 THEN
        RAISE EXCEPTION 'Invalid image seed count';
    END IF;

    IF (SELECT COUNT(*) FROM _en_users) <> 5 THEN
        RAISE EXCEPTION 'Invalid demo user seed count';
    END IF;
END
$validate$;

UPDATE public.recipes AS r
SET title = e.title, description = e.description,
    instructions = e.instructions, notes = e.notes
FROM _en_recipes AS e WHERE r.id = e.id;

UPDATE public.categories AS c
SET name = e.name, description = e.description
FROM _en_categories AS e WHERE c.id = e.id;

UPDATE public.recipe_ingredients AS i
SET name = e.name, unit = e.unit, notes = e.notes
FROM _en_ingredients AS e WHERE i.id = e.id;

UPDATE public.recipe_steps AS s
SET title = e.title, description = e.description
FROM _en_steps AS e WHERE s.id = e.id;

UPDATE public.recipe_images AS i
SET alt_text = e.alt_text
FROM _en_images AS e WHERE i.id = e.id;

UPDATE public.users AS u
SET full_name = e.full_name, bio = e.bio
FROM _en_users AS e WHERE u.id = e.id;

-- Scope: all culinary content, including three extra categories.
-- The category previously named 123 becomes Miscellaneous Recipes.
-- Category slugs and all foreign keys are preserved.
-- Six unrelated user profiles and all authentication data unchanged.

SELECT (SELECT COUNT(*) FROM _en_recipes) AS translated_recipes,
       (SELECT COUNT(*) FROM _en_categories) AS translated_categories,
       (SELECT COUNT(*) FROM _en_ingredients) AS translated_ingredients,
       (SELECT COUNT(*) FROM _en_steps) AS translated_steps,
       (SELECT COUNT(*) FROM _en_images) AS translated_images,
       (SELECT COUNT(*) FROM _en_users) AS translated_demo_chefs;

COMMIT;
