    ('16043248-2457-4868-83f6-001ee199899d', 'Spicy Sichuan Mapo Tofu', 'Silken tofu and minced pork simmered in spicy Sichuan bean sauce with numbing peppercorns.', 'Follow the numbered preparation and cooking steps below for this recipe.', 'Use fresh, high-quality ingredients and adjust seasoning to taste.'),
    ('0a638ac2-15f4-4c79-88a1-5e7f87ce0d7f', 'Hue Noodles with Fermented Fish Sauce and Roast Pork', 'Rice noodles served with savory fermented fish sauce, tender boiled pork, crispy roast pork, and herbs.', 'Follow the numbered preparation and cooking steps below for this recipe.', 'Use fresh, high-quality ingredients and adjust seasoning to taste.'),
    ('c5e8e678-e6a6-450b-9f42-8ab20c066978', 'Nha Trang Green Chili Seafood Dipping Sauce', 'Bright tangy seafood dip made with green chilies, lime, condensed milk, and finely shredded lime leaves.', 'Follow the numbered preparation and cooking steps below for this recipe.', 'Use fresh, high-quality ingredients and adjust seasoning to taste.'),
    ('87ff098a-38ab-4826-8a9e-072640aae53b', 'Crystal Shrimp Dumplings', 'Translucent steamed dumplings packed with sweet shrimp and served with a tangy chili-soy dip.', 'Follow the numbered preparation and cooking steps below for this recipe.', 'Use fresh, high-quality ingredients and adjust seasoning to taste.');
INSERT INTO _en_categories (id, name, description) VALUES
