    ('44444444-4444-4444-0100-000000000010', 'Naturally brewed soy sauce', 'tbsp', 'Choose traditionally fermented soy sauce.');
INSERT INTO _en_steps (id, title, description) VALUES
    ('55555555-5555-5555-0001-000000000001', 'Step 1: Prepare the Fresh Ingredients', 'Rinse all meat, seafood, and vegetables thoroughly in lightly salted water. Pat proteins dry before marinating, then pick tender herb leaves and drain well.'),
    ('55555555-5555-5555-0001-000000000002', 'Step 2: Mix the Signature Marinade', 'Combine minced garlic, fried shallots, fish sauce, black pepper, honey, and oyster sauce in a bowl. Stir until the seasonings dissolve into a smooth marinade.'),
    ('55555555-5555-5555-0001-000000000003', 'Step 3: Marinate for Full Flavor', 'Coat the meat evenly with the prepared marinade and massage it in gently. Cover and refrigerate for at least 30 to 45 minutes.'),
    ('55555555-5555-5555-0001-000000000004', 'Step 4: Slowly Simmer the Broth', 'Place blanched bones and fragrant spices in a stockpot with two liters of hot water. Simmer gently and skim the surface regularly to keep the broth clear.'),
    ('55555555-5555-5555-0001-000000000005', 'Step 5: Cook Over High Heat', 'Heat a deep pan with a little scallion oil or cooking oil. Stir-fry the ingredients quickly over high heat until fragrant and just cooked through.'),
    ('55555555-5555-5555-0001-000000000006', 'Step 6: Adjust and Balance the Seasoning', 'Taste the sauce and adjust fish sauce and rock sugar until salty, sweet, sour, and mildly spicy notes are balanced.'),
    ('55555555-5555-5555-0001-000000000007', 'Step 7: Plate and Serve', 'Transfer the hot dish to a serving plate or bowl. Finish with cracked pepper, golden fried shallots, and fresh cilantro; serve immediately.'),
