INSERT INTO _en_users (id, full_name, bio) VALUES
    ('11111111-1111-1111-1111-111111111111', 'Executive Chef Admin', 'Executive chef with 18 years of experience in Indochinese culinary arts.'),
    ('11111111-1111-1111-1111-000000000002', 'Chef Nguyen Van Minh', 'Traditional pho specialist and master of Hanoi-style clay pot braises.'),
    ('11111111-1111-1111-1111-000000000003', 'Le Thuc Doan', 'Artisan baker and specialist in modern French-Asian desserts.'),
    ('11111111-1111-1111-1111-000000000004', 'Tran Mai Anh', 'Clinical nutrition expert and creator of healthy, wholesome meal plans.'),
    ('11111111-1111-1111-1111-000000000005', 'Marco Rossi', 'Italian chef blending Mediterranean cuisine with tropical spices.');
